26	export default async function AccountPage({
27	  searchParams,
28	}: {
29	  searchParams: Promise<{ booked?: string }>;
30	}) {
31	  const profile = await requireRole("customer");
32	  const { booked } = await searchParams;
33	
34	  const [bookings, sessions, payments, reviews, favorites] = await Promise.all([
35	    listCustomerBookings(profile.id),
36	    listCustomerCompletedSessions(profile.id),
37	    listCustomerPayments(profile.id),
38	    listCustomerReviews(profile.id),
39	    listFavoriteProviders(profile.id),
40	  ]);
41	
42	  // Resolve listener names for bookings + sessions.
43	  const providerIds = Array.from(
44	    new Set([
45	      ...bookings.map((b) => b.provider_id),
46	      ...sessions.map((s) => s.provider_id),
47	    ]),
48	  );
49	  const providersById = await getApprovedProvidersByIds(providerIds);
50	  const nameFor = (id: string) => providersById.get(id)?.display_name ?? "—";
51	
52	  const favoritesWithAudio = await Promise.all(
53	    favorites.map(async (provider) => ({
54	      provider,
55	      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
56	    })),
57	  );
58	
59	  const upcoming = bookings
60	    .filter((b) => b.status === "confirmed" || b.status === "in_progress")
61	    .map((b) => ({
62	      id: b.id,
63	      providerName: nameFor(b.provider_id),
64	      blockMinutes: b.block_minutes,
65	      whenLabel: b.scheduled_at
66	        ? shortDate(b.scheduled_at)
67	        : t("account.talkNow"),
68	    }));
69	
70	  const next = upcoming[0];
71	
72	  const reviewedSessionIds = new Set(
73	    reviews.map((r) => r.session_id).filter(Boolean),
74	  );
75	  const pastRows = sessions.map((s) => ({
76	    id: s.id,
77	    bookingId: s.booking_id,
78	    dateLabel: shortDate(s.ended_at),
79	    endedAtMs: s.ended_at ? new Date(s.ended_at).getTime() : 0,
80	    listenerName: nameFor(s.provider_id),
81	    durationLabel: durationLabel(s.elapsed_seconds),
82	    amountCents: s.total_price_cents,
83	    hasReview: reviewedSessionIds.has(s.id),
84	  }));
85	
86	  return (
87	    <div className="flex flex-col gap-8">
88	      <DashboardHeader
89	        title={t("account.title")}
90	        description={t("account.subtitle")}
91	        action={
92	          <Link href="/account/settings" className="rounded-btn">
93	            <Button variant="ghost" icon={Settings}>
94	              {t("account.settingsLink")}
95	            </Button>
96	          </Link>
97	        }
98	      />
99	
100	      {booked ? (
101	        <Card
102	          role="status"
103	          className="flex items-center gap-3 border-l-4 border-success bg-success-tint"
104	        >
105	          <CircleCheck size={22} aria-hidden="true" className="text-success" />
106	          <p className="text-base font-bold text-ink">
107	            {t("account.bookedConfirmed")}
108	          </p>
109	        </Card>
110	      ) : null}
111	
112	      {/* Resume / quick start */}
113	      <Card
114	        as="section"
115	        className="flex flex-col gap-4 bg-primary-tint sm:flex-row sm:items-center sm:justify-between"
116	      >
117	        <div className="flex flex-col gap-1">
118	          <h2 className="text-h3">{t("account.resumeHeading")}</h2>
119	          <p className="text-base text-ink-soft">
120	            {next
121	              ? `${t("account.nextSession")}: ${next.providerName} · ${next.whenLabel}`
122	              : t("account.nextSessionNone")}
123	          </p>
124	        </div>
125	        <div className="flex flex-wrap gap-3">
126	          {next ? (
127	            <Link href={`/session/${next.id}`} className="rounded-btn">
128	              <Button variant="ghost">{t("account.join")}</Button>
129	            </Link>
130	          ) : null}
131	          <Link href="/browse?available=1" className="rounded-btn">
132	            <Button icon={Phone}>{t("account.talkNow")}</Button>
133	          </Link>
134	        </div>
135	      </Card>
136	
137	      {/* Favorites */}
138	      <section className="flex flex-col gap-4">
139	        <h2 className="text-h2">{t("account.favoritesHeading")}</h2>
140	        <FavoriteListeners items={favoritesWithAudio} />
141	      </section>
142	
143	      {/* Upcoming bookings */}
144	      <section className="flex flex-col gap-4">
145	        <h2 className="text-h2">{t("account.upcomingHeading")}</h2>
146	        <UpcomingBookings items={upcoming} />
147	      </section>
148	
149	      {/* Past sessions */}
150	      <section className="flex flex-col gap-4">
151	        <h2 className="text-h2">{t("account.pastHeading")}</h2>
152	        <PastSessionsTable rows={pastRows} />
153	      </section>
154	
155	      {/* Receipts */}
156	      <section className="flex flex-col gap-4">
157	        <h2 className="text-h2">{t("account.receiptsHeading")}</h2>
158	        {payments.length === 0 ? (
159	          <Card>
160	            <p className="text-base text-ink-soft">{t("account.receiptsNone")}</p>
161	          </Card>
162	        ) : (
163	          <ul className="flex flex-col gap-3">
164	            {payments.map((p) => (
165	              <Card
166	                as="li"
167	                key={p.id}
168	                className="flex flex-wrap items-center justify-between gap-3"
169	              >
170	                <div className="flex items-center gap-3">
171	                  <span className="text-base font-bold text-ink">
172	                    {formatCents(p.amount_cents)}
173	                  </span>
174	                  <StatusBadge
175	                    tone={p.status === "captured" ? "success" : "neutral"}
176	                  >
177	                    {p.status}
178	                  </StatusBadge>
179	                  <span className="text-sm text-ink-soft">
180	                    {shortDate(p.created_at)}
181	                  </span>
182	                </div>
183	                <a
184	                  href={`/account/receipt/${p.booking_id}`}
185	                  className="inline-flex items-center gap-1.5 text-base font-bold text-primary underline underline-offset-[3px]"
186	                >
187	                  <Download size={16} strokeWidth={2} aria-hidden="true" />
188	                  {t("account.download")}
189	                </a>
190	              </Card>
191	            ))}
192	          </ul>
193	        )}
194	      </section>
195	    </div>
196	  );
197	}
